type Events = {
  login: { userId: number };
  logout: void;
};

class EventEmitter<T> {
  private listeners: { [K in keyof T]?: Function[] } = {};

  on<K extends keyof T>(event: K, callback: (payload: T[K]) => void) {
    this.listeners[event] = this.listeners[event] || [];
    this.listeners[event]!.push(callback);
  }

  emit<K extends keyof T>(event: K, payload: T[K]) {
    this.listeners[event]?.forEach(fn => fn(payload));
  }
}

const emitter = new EventEmitter<Events>();

emitter.on('login', (data) => {
  console.log(data.userId);
});

emitter.emit('login', { userId: 1 });

class Container {
  private services = new Map();

  register<T>(key: string, value: T) {
    this.services.set(key, value);
  }

  get<T>(key: string): T {
    return this.services.get(key);
  }
}

const container = new Container();

container.register('logger', console);

const logger = container.get<Console>('logger');

logger.log('Hello DI');

type Context = {
  user?: string;
};

type Middleware = (ctx: Context, next: () => void) => void;

class Pipeline {
  private middlewares: Middleware[] = [];

  use(fn: Middleware) {
    this.middlewares.push(fn);
  }

  execute(ctx: Context) {
    let index = 0;

    const next = () => {
      const fn = this.middlewares[index++];
      if (fn) fn(ctx, next);
    };

    next();
  }
}

const app = new Pipeline();

app.use((ctx, next) => {
  ctx.user = 'Nacho';
  next();
});

app.execute({});

class QueryBuilder {
  private query: string = '';

  select(fields: string) {
    this.query += `SELECT ${fields} `;
    return this;
  }

  from(table: string) {
    this.query += `FROM ${table} `;
    return this;
  }

  build() {
    return this.query;
  }
}

const query = new QueryBuilder()
  .select('*')
  .from('users')
  .build();

