function promiseAll<T extends any[]>(promises: [...T]): Promise<T> {
  return Promise.all(promises) as any;
}

const result = promiseAll([
  Promise.resolve(1),
  Promise.resolve('hello')
]);

result.then(console.log);

function memoize<T extends (...args: any[]) => any>(fn: T) {
  const cache = new Map();

  return function (...args: Parameters<T>): ReturnType<T> {
    const key = JSON.stringify(args);

    if (cache.has(key)) return cache.get(key);

    const result = fn(...args);

    cache.set(key, result);

    return result;
  };
}

const add = memoize((a: number, b: number) => a + b);

console.log(add(2, 3));

type State = 'idle' | 'loading' | 'success' | 'error';

type Transition = {
  idle: 'loading';
  loading: 'success' | 'error';
  success: 'idle';
  error: 'idle';
};

class Machine {
  state: State = 'idle';

  transition(next: State) {
    this.state = next;
  }
}

const m = new Machine();

m.transition('loading');
console.log(m.state);

type Plugin = {
  name: string;
  execute: () => void;
};

class PluginSystem {
  private plugins: Plugin[] = [];

  register(plugin: Plugin) {
    this.plugins.push(plugin);
  }

  run() {
    this.plugins.forEach(p => p.execute());
  }
}

const system = new PluginSystem();

system.register({
  name: 'logger',
  execute: () => console.log('logging...')
});

system.run();

type Events = {
  message: string;
};

class EventBus {
  private listeners: { [K in keyof Events]?: Function[] } = {};

  on<K extends keyof Events>(event: K, cb: (payload: Events[K]) => Promise<void> | void) {
    this.listeners[event] = this.listeners[event] || [];
    this.listeners[event]!.push(cb);
  }

  async emit<K extends keyof Events>(event: K, payload: Events[K]) {
    const handlers = this.listeners[event] || [];

    await Promise.all(handlers.map(h => h(payload)));
  }
}

const bus = new EventBus();

bus.on('message', async (msg) => {
  console.log(msg);
});

bus.emit('message', 'hello world');
